-- Alpha1: source sheets generated by CI from original procedural model v2.
-- Identical frame geometry/pivot for native body, color mask and script overlay.
local root="__ElectrifiedMainline__/graphics/entity/locomotive-049/"
local function layer(name)
    return {filename=root..name..".png",width=512,height=512,direction_count=32,
        line_length=8,scale=0.5,shift={0,-1},apply_projection=false,
        dice=4,priority="high",usage="train"}
end
local body,mask,shadow=layer("body"),layer("mask"),layer("shadow")
mask.flags={"mask"};mask.apply_runtime_tint=true;mask.tint_as_overlay=true
shadow.flags={"shadow"};shadow.draw_as_shadow=true
local loco=assert(data.raw.locomotive["em-electric-locomotive"])
loco.pictures={rotated={layers={body,mask,shadow}}}
-- Native wheel art, physical properties, item and color policy stay inherited.
-- No headlights or human cabin in the approved autonomous concept.
loco.front_light=nil
loco.front_light_pictures=nil
loco.back_light=nil
loco.stand_by_light=nil
loco.water_reflection=nil
local sprites={}
for _,state in ipairs({"up","down"}) do
    for i=0,31 do
        sprites[#sprites+1]={type="sprite",name=string.format("em-panto-049-%s-%02d",state,i),
            filename=root.."pantograph-"..state..".png",width=512,height=512,
            x=(i%8)*512,y=math.floor(i/8)*512,scale=0.5,priority="high"}
    end
end
data:extend(sprites)
